import{_ as t,a,c as r,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · 单元 4 复习与自测 · 第94–96课","description":"L73–L96 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 4 复习与自测 · 第94–96课","description":"L73–L96 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-04/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 4 复习与自测","summary":"L73–L96 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 4 复习与自测 · 第87–93课","link":"/life/english/new-concept/book-1/unit-04/review-part-03"},"next":{"text":"第一册：英语初阶 · 单元 5：转述、程度比较与过去先后","link":"/life/english/new-concept/book-1/unit-05/overview"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 4 复习与自测 · 第87–93课","link":"/life/english/new-concept/book-1/unit-04/review-part-03"},"next":{"text":"第一册：英语初阶 · 单元 5：转述、程度比较与过去先后","link":"/life/english/new-concept/book-1/unit-05/overview"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-04/review-part-04.md","filePath":"life/english/new-concept/book-1/unit-04/review-part-04.md"}'),s={name:"life/english/new-concept/book-1/unit-04/review-part-04.md"};function o(i,e,l,d,h,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-单元-4-复习与自测-·-第94–96课" tabindex="-1">第一册：英语初阶 · 单元 4 复习与自测 · 第94–96课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-4-复习与自测-·-第94–96课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 4 复习与自测 · 第94–96课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-04/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-04/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-94-·-过去、现在与将来的时间线" tabindex="-1">Lesson 94 · 过去、现在与将来的时间线 <a class="header-anchor" href="#lesson-94-·-过去、现在与将来的时间线" aria-label="Permalink to &quot;Lesson 94 · 过去、现在与将来的时间线 {#lesson-94-·-过去、现在与将来的时间线}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> He will return next Tuesday.</p><h3 id="练习-1-21" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-21" aria-label="Permalink to &quot;练习 1 {#练习-1-21}&quot;">​</a></h3><p>补将来助动词：He ___ return next Tuesday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> will</p><p><strong>解析：</strong> 按本课规则判断：先确定时间再选动词形式：过去 go→went，未来 will go，现在习惯 go/goes。问过去用 did + 原形，问未来用 will + 原形。tomorrow、last year 等时间词提供线索，但要结合整个叙述。多句对比中，人称变化和时态变化是两个独立检查项，不能只改时间词而保留错误谓语。</p></details><p><strong>表达迁移：</strong> 围绕“比较过去经历与未来计划”写两至三句，再读给同伴听。至少使用一次过去、现在与将来的时间线，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>He will return next Tuesday. Our neighbour flew to Madrid last week.</p><p>Will return 为将来结构，return 用原形；next Tuesday 前不用 on。 Flew 是 fly 的过去式，last week 指明确过去；to Madrid 表飞行目的地。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-094">回看本课</a></p><h2 id="lesson-95-·-had-better-与时间表达" tabindex="-1">Lesson 95 · had better 与时间表达 <a class="header-anchor" href="#lesson-95-·-had-better-与时间表达" aria-label="Permalink to &quot;Lesson 95 · had better 与时间表达 {#lesson-95-·-had-better-与时间表达}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We had better leave before the traffic gets heavy.</p><h3 id="练习-1-22" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-22" aria-label="Permalink to &quot;练习 1 {#练习-1-22}&quot;">​</a></h3><p>补原形：We had better ___ (leave) now.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> leave</p><p><strong>解析：</strong> 按本课规则判断：had better + 动词原形表示在当前情境下最好做某事，常带不这样做会有后果的意味。虽然含 had，整体不表示过去；否定为 had better not + 原形。时间可用直接读法 ten twenty，或 twenty past ten。问确切发车时间时要明确日期与上午下午，避免只说含糊钟点。</p></details><p><strong>表达迁移：</strong> 围绕“询问准确时间并作出建议”写两至三句，再读给同伴听。至少使用一次had better 与时间表达，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We had better leave before the traffic gets heavy. You had better not miss the last train.</p><p>Had better 后直接接 leave，表示当前建议；before the traffic gets heavy 是时间从句，用现在时表达将来。 Had better not 加 miss 表否定建议；the last train 为宾语，had better 不是过去发生的动作。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-095">回看本课</a></p><h2 id="lesson-96-·-had-better-与时间表达" tabindex="-1">Lesson 96 · had better 与时间表达 <a class="header-anchor" href="#lesson-96-·-had-better-与时间表达" aria-label="Permalink to &quot;Lesson 96 · had better 与时间表达 {#lesson-96-·-had-better-与时间表达}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> You had better not miss the last train.</p><h3 id="练习-1-23" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-23" aria-label="Permalink to &quot;练习 1 {#练习-1-23}&quot;">​</a></h3><p>将 You had better wait. 改为否定。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> You had better not wait.</p><p><strong>解析：</strong> 按本课规则判断：had better + 动词原形表示在当前情境下最好做某事，常带不这样做会有后果的意味。虽然含 had，整体不表示过去；否定为 had better not + 原形。时间可用直接读法 ten twenty，或 twenty past ten。问确切发车时间时要明确日期与上午下午，避免只说含糊钟点。</p></details><p><strong>表达迁移：</strong> 围绕“询问准确时间并作出建议”写两至三句，再读给同伴听。至少使用一次had better 与时间表达，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>You had better not miss the last train. We had better leave before the traffic gets heavy.</p><p>Had better not 加 miss 表否定建议；the last train 为宾语，had better 不是过去发生的动作。 Had better 后直接接 leave，表示当前建议；before the traffic gets heavy 是时间从句，用现在时表达将来。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-096">回看本课</a></p>',28)])])}const g=t(s,[["render",o]]);export{u as __pageData,g as default};
